// GPR/FPR/CSR drain is Abstract-Command-only: every register and CSR is read
// one abstract command each, directly into the drained state. The Program
// Buffer carries only what abstract commands cannot reach (the V dump sweep,
// L2C MMIO), so a drain of a non-V, non-L2C state must issue NO PB execution.
TEST_CASE("drain reads GPRs and FPRs via abstract reads only -- no PB "
          "store-sweep, even when the V region leaves scratch room")
{
  RecordingBus bus;
  bus.dmstatus_value   = kDmstatusHaltedAndAcked;
  bus.abstractcs_value = 8u << 24;  // progbufsize = 8
  for (uint16_t i = 1; i < 32; ++i)
    bus.regfile[hybrid::regno_gpr(i)] = 0xC0000000ULL + i;
  for (uint16_t i = 0; i < 32; ++i)
    bus.regfile[hybrid::regno_fpr(i)] = 0xD0000000ULL + i;
  bus.regfile[hybrid::regno_csr(RD::kCsrFcsr)] = 0x45;

  hybrid_state_v1 input{};
  input.magic   = HYBRID_STATE_MAGIC;
  input.version = HYBRID_STATE_VERSION;
  input.flags   = HYBRID_FLAG_RV64 | HYBRID_FLAG_FP;
  input.priv    = 3;
  input.vlenb   = 64;

  hybrid::StateDrain drain(bus, kScratch);
  const auto state = drain.drain_with_passthrough(input);

  // Every GPR/FPR value arrives via its abstract read...
  for (int i = 1; i < 32; ++i)
    CHECK(state.gpr[i] == 0xC0000000ULL + uint64_t(i));
  for (int i = 0; i < 32; ++i)
    CHECK(state.fpr[i] == 0xD0000000ULL + uint64_t(i));
  CHECK(state.fcsr == 0x45u);

  // ...and no Program-Buffer execution occurred at all -- with no V state and
  // no L2C there is nothing the abstract command space cannot reach.
  for (const auto& op : bus.ops)
    CHECK_FALSE((op.kind == DmiOp::Kind::Write && op.reg == RD::kCommand
                 && op.value == hybrid::kExecProgbufCmd));
}

TEST_CASE("CSR drain is Abstract-Command-only: every Andes+M-ext CSR gets its "
          "own abstract read, never a Program-Buffer csrr+sd sweep")
{
  RecordingBus bus;
  bus.dmstatus_value   = kDmstatusHaltedAndAcked;
  bus.abstractcs_value = 8u << 24;  // progbufsize=8: a batch would fit here

  hybrid_state_v1 input{};
  input.magic   = HYBRID_STATE_MAGIC;
  input.version = HYBRID_STATE_VERSION;
  input.flags   = HYBRID_FLAG_RV64 | HYBRID_FLAG_ANDES | HYBRID_FLAG_M_EXT;
  input.priv    = 3;
  input.vlenb   = 0;  // no V PB traffic: isolate the CSR drain path

  // Preload the regfile so every transported CSR has a distinct value.
  std::vector<uint16_t> addrs;
  hybrid::for_each_transport_csr(input, hybrid::AndesCaps::all(),
    [&](uint16_t a, const uint64_t&) { addrs.push_back(a); });
  REQUIRE(!addrs.empty());
  for (std::size_t k = 0; k < addrs.size(); ++k)
    bus.regfile[hybrid::regno_csr(addrs[k])] = 0xC5000000ULL + k;

  hybrid::StateDrain drain(bus, kScratch);
  auto state = drain.drain_with_passthrough(input);

  // (a) every transported CSR's value landed in the state via its own
  //     abstract read.
  std::size_t k = 0;
  hybrid::for_each_transport_csr(state, hybrid::AndesCaps::all(),
    [&](uint16_t, uint64_t& field) {
      CHECK(field == 0xC5000000ULL + k);
      ++k;
    });

  // (b) no Program-Buffer execution occurred at all -- with no V state and no
  //     L2C, the only possible PB user would have been a CSR sweep.
  for (const auto& op : bus.ops)
    CHECK_FALSE((op.kind == DmiOp::Kind::Write && op.reg == RD::kCommand
                 && op.value == hybrid::kExecProgbufCmd));
}

// ---- v5: L2C MMIO config read-back -----------------------------------------
// The dual of ResumeDriver::restore_l2c: re-read the writable L2C config
// registers via Program-Buffer word loads so the --verify oracle sees the
// round-tripped values, not the stale QEMU1 passthrough. Gated on the engine
// having an L2C (set_l2c); a load from an absent region would fault the PB.

static std::size_t count_pb_insn(const std::vector<DmiOp>& ops, uint32_t insn)
{
  std::size_t n = 0;
  for (const auto& op : ops)
    if (op.kind == DmiOp::Kind::Write && op.reg == hybrid::kProgbuf0
        && op.value == insn)
      ++n;
  return n;
}

TEST_CASE("v5: drain_with_passthrough re-reads writable L2C config regs when flag + engine present")
{
  RecordingBus bus;
  bus.dmstatus_value = kDmstatusHaltedAndAcked;
  // The value the hart returns for the PB lwu read-back (staged into x5).
  bus.regfile[hybrid::regno_gpr(5)] = 0x1ULL;  // CEN=1 read back

  hybrid_state_v1 input{};
  input.magic   = HYBRID_STATE_MAGIC;
  input.version = HYBRID_STATE_VERSION;
  input.flags   = HYBRID_FLAG_RV64 | HYBRID_FLAG_L2C;
  input.l2c.reg[HYBRID_L2C_OFF_CONTROL / 8] = 0xDEADULL;  // stale; must be overwritten

  hybrid::StateDrain drain(bus, kScratch);
  drain.set_l2c(/*present=*/true, /*base=*/0xE0500000ull);
  const auto state = drain.drain_with_passthrough(input);

  // The control slot is the fresh DM read-back (0x1), not the stale passthrough.
  CHECK(state.l2c.reg[HYBRID_L2C_OFF_CONTROL / 8] == 0x1ULL);

  // Each read-back is `lwu x5, 0(x6)`: Control + HPM Control + Way Masks.
  CHECK(count_pb_insn(bus.ops, hybrid::encode_lwu(5, 6, 0)) == 2u + HYBRID_L2C_WAYMASK_NUM);

  // The control register's MMIO address (base + 0x0008) was staged into x6.
  bool addr_staged = false;
  for (const auto& op : bus.ops)
    if (op.kind == DmiOp::Kind::Write
        && op.reg == hybrid::ResumeDriver::kData0
        && op.value == 0xE0500008u)
      addr_staged = true;
  CHECK(addr_staged);
}

TEST_CASE("v5: drain_with_passthrough leaves L2C untouched when the engine has no L2C")
{
  RecordingBus bus;
  bus.dmstatus_value = kDmstatusHaltedAndAcked;

  hybrid_state_v1 input{};
  input.magic   = HYBRID_STATE_MAGIC;
  input.version = HYBRID_STATE_VERSION;
  input.flags   = HYBRID_FLAG_RV64 | HYBRID_FLAG_L2C;
  input.l2c.reg[HYBRID_L2C_OFF_CONTROL / 8] = 0xDEADULL;

  hybrid::StateDrain drain(bus, kScratch);
  // set_l2c NOT called: no L2C region. The passthrough must survive untouched.
  const auto state = drain.drain_with_passthrough(input);

  CHECK(state.l2c.reg[HYBRID_L2C_OFF_CONTROL / 8] == 0xDEADULL);
  CHECK(count_pb_insn(bus.ops, hybrid::encode_lwu(5, 6, 0)) == 0u);
}

