// ---- v5: L2C MMIO config read-back -----------------------------------------
// The dual of ResumeDriver::restore_l2c: re-read the writable L2C config
// registers via Program-Buffer word loads so the --verify oracle sees the
// round-tripped values, not the stale QEMU1 passthrough. Gated on the engine
// having an L2C (set_l2c); a load from an absent region would fault the PB.

static std::size_t count_pb_insn(const std::vector<DmiOp>& ops, uint32_t insn)
{
  std::size_t n = 0;
  for (const auto& op : ops)
    if (op.kind == DmiOp::Kind::Write && op.reg == hybrid::kProgbuf0
        && op.value == insn)
      ++n;
  return n;
}

TEST_CASE("v5: drain_with_passthrough re-reads writable L2C config regs when flag + engine present")
{
  RecordingBus bus;
  bus.dmstatus_value = kDmstatusHaltedAndAcked;
  // The value the hart returns for the PB lwu read-back (staged into x5).
  bus.regfile[hybrid::regno_gpr(5)] = 0x1ULL;  // CEN=1 read back

  hybrid_state_v1 input{};
  input.magic   = HYBRID_STATE_MAGIC;
  input.version = HYBRID_STATE_VERSION;
  input.flags   = HYBRID_FLAG_RV64 | HYBRID_FLAG_L2C;
  input.l2c.reg[HYBRID_L2C_OFF_CONTROL / 8] = 0xDEADULL;  // stale; must be overwritten

  hybrid::StateDrain drain(bus, kScratch);
  drain.set_l2c(/*present=*/true, /*base=*/0xE0500000ull);
  const auto state = drain.drain_with_passthrough(input);

  // The control slot is the fresh DM read-back (0x1), not the stale passthrough.
  CHECK(state.l2c.reg[HYBRID_L2C_OFF_CONTROL / 8] == 0x1ULL);

  // Each read-back is `lwu x5, 0(x6)`: Control + HPM Control + Way Masks.
  CHECK(count_pb_insn(bus.ops, hybrid::encode_lwu(5, 6, 0)) == 2u + HYBRID_L2C_WAYMASK_NUM);

  // The control register's MMIO address (base + 0x0008) was staged into x6.
  bool addr_staged = false;
  for (const auto& op : bus.ops)
    if (op.kind == DmiOp::Kind::Write
        && op.reg == hybrid::ResumeDriver::kData0
        && op.value == 0xE0500008u)
      addr_staged = true;
  CHECK(addr_staged);
}

